        for (i = 0; i < buf_size; i++) {
            if ((buf[i] == 0x00) && (i + 3 < buf_size) &&
                (buf[i + 1] == 0x00) && (buf[i + 2] == 0x01)) {
                dctx->frame_start = i;
                dctx->frame_start_found = 1;
                break;
            }
        }
    }

    if (dctx->frame_start_found) {
        if (dctx->frame_info_parsed) {
            int remaining = dctx->current_frame_size - dctx->frame_offset;
            if (remaining <= buf_size) {
                dctx->frame_start_found = 0;
                dctx->frame_info_parsed = 0;
                return remaining;
            } else {
                dctx->frame_offset += buf_size;
                return END_NOT_FOUND;
            }
        } else {
            if (buf_size - dctx->frame_offset >= 4) {
                int width = (buf[dctx->frame_offset + 3] >> 2) & 0x3F;
