                dctx->frame_offset += buf_size;
            }
        }
    }

    return END_NOT_FOUND;
}

int find_dnxhd_frame_end(DNXHDParserContext *dctx, const uint8_t *buf, int buf_size) {
    const uint8_t *buf_end = buf + buf_size;
    const uint8_t *p = buf;
    const uint8_t *header_prefix = NULL;

    if (!dctx->frame_start_found) {
        // Search for header prefix in buffer
        while (p < buf_end - 3) {
            if ((p[0] == 0x00 && p[1] == 0x00 && p[2] == 0x01 && p[3] == 0x20) ||
                (p[0] == 0x00 && p[1] == 0x00 && p[2] == 0x01 && p[3] == 0x21)) {
                header_prefix = p;
                break;
            }
            p++;
        }

        if (header_prefix) {
            dctx->frame_start = header_prefix;
            dctx->frame_start_found = 1;

            // Read frame dimensions and other info from header
            uint32_t header = (header_prefix[4] << 24) | (header_prefix[5] << 16) |
                              (header_prefix[6] << 8) | header_prefix[7];

            dctx->width = (header >> 20) & 0x03FF;
            dctx->height = (header >> 8) & 0x03FF;
            dctx->interlaced = (header >> 19) & 0x0001;

            if (dctx->interlaced) {
                dctx->bytes_per_frame = 2 * dctx->width * dctx->height;
            } else {
                dctx->bytes_per_frame = dctx->width * dctx->height;
            }

            dctx->bytes_read = 0;
        }
    }

    if (dctx->frame_start_found) {
        int bytes_remaining = dctx->bytes_per_frame - dctx->bytes_read;
        int bytes_in_buffer = buf_size;

        if (bytes_in_buffer >= bytes_remaining) {
            dctx->frame_start_found = 0;
            return bytes_remaining;
        } else {
            dctx->bytes_read += bytes_in_buffer;
            return END_NOT_FOUND;
        }
    }

    return END_NOT_FOUND;
}

