}

int find_dnxhd_frame_end(DNXHDParserContext *dctx, const uint8_t *buf, int buf_size) {
    int i;

    if (!dctx->frame_start_found) {
        // Search for header prefix
        for (i = 0; i < buf_size - 3; i++) {
            if (buf[i] == 0x00 && buf[i + 1] == 0x00 && buf[i + 2] == 0x01) {
                // Found header prefix
                dctx->frame_start_found = 1;
                dctx->current_pos = i + 3;
                break;
            }
        }
    }

    if (dctx->frame_start_found) {
        int remaining_bytes = dctx->frame_size - dctx->current_pos;

        if (remaining_bytes <= buf_size) {
            // End of frame is found in the buffer
            dctx->frame_start_found = 0;
            dctx->current_pos = 0;
            dctx->frame_size = 0;

            if (dctx->interlaced) {
                dctx->field = !dctx->field;
            }

            return remaining_bytes;
        } else {
            // Not enough data to complete the frame
            dctx->current_pos += buf_size;
            return END_NOT_FOUND;
        }
    }

    return END_NOT_FOUND;
}
